<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue';import { auditApi,type AuditLog } from '@/api/modules'
const rows=ref<AuditLog[]>([]),total=ref(0),loading=ref(false);const query=reactive({page:1,pageSize:20})
async function load(){loading.value=true;try{const result=await auditApi.list(query);rows.value=result.records;total.value=result.total}finally{loading.value=false}}onMounted(load)
</script>
<template><section class="workspace"><header class="page-head"><div><h1>审计日志</h1><p>查看家庭、账号与权限相关操作轨迹</p></div><el-button @click="load">刷新</el-button></header><div class="surface"><el-table v-loading="loading" :data="rows"><el-table-column prop="createdAt" label="时间" width="190"><template #default="s">{{new Date(s.row.createdAt).toLocaleString('zh-CN')}}</template></el-table-column><el-table-column prop="familyId" label="家庭 ID" width="100"/><el-table-column prop="operatorId" label="操作人 ID" width="110"/><el-table-column prop="action" label="动作" min-width="180"/><el-table-column prop="resourceType" label="资源"/><el-table-column prop="resourceId" label="资源 ID"/><el-table-column prop="result" label="结果"><template #default="s"><el-tag type="success" effect="plain">{{s.row.result}}</el-tag></template></el-table-column></el-table><el-empty v-if="!loading&&!rows.length" description="暂无审计记录"/></div><el-pagination v-if="total>query.pageSize" class="mt-5 justify-end" v-model:current-page="query.page" :page-size="query.pageSize" :total="total" @current-change="load"/></section></template>
